    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    def f(x):
        while x % k == 0:
            x = x // k
        return x

    from collections import deque

    # State is a tuple of numbers (preserves multiplicity)
    initial_state = tuple(sorted(a))

    if len(initial_state) == 1:
        if initial_state == (1,):
            return "YES\n"
        else:
            return "NO"

    queue = deque([(initial_state, [])])
    visited = {initial_state}

    while queue:
        state, ops = queue.popleft()

        if len(state) == 1:
            if state[0] == 1:
                # Reconstruct operations
                result = "YES\n"
                for x, y in ops:
                    result += f"{x} {y}\n"
                return result
            else:
                continue

        # Try all pairs
        length = len(state)
        for i in range(length):
            for j in range(i + 1, length):
                x = state[i]
                y = state[j]

                new_val = f(x + y)
                new_list = list(state)
                new_list.pop(i)
                new_list.pop(j)

                new_list.append(new_val)
                new_list.sort()
                new_state = tuple(new_list)

                if new_state not in visited:
                    visited.add(new_state)
                    new_ops = [(x, y)] + ops
                    queue.append((new_state, new_ops))

    return "NO\n"
