    for i in range(m):
        u, v, w = map(int, lines[2 + i].split())
        edges.append((u, v, w, i + 1))
        adj[u].append((v, i))
        adj[v].append((u, i))

    def is_connected(ignore_edge=None):
        if ignore_edge is not None:
            # Filter out the ignored edge
            filtered_adj = [[] for _ in range(n + 1)]
            for u in range(1, n + 1):
                for v, idx in adj[u]:
                    if idx != ignore_edge[0]:
                        filtered_adj[u].append((v, idx))
            return dfs_reachable(filtered_adj, s, t)
        return dfs_reachable(adj, s, t)

    def dfs_reachable(adj_list, start, target):
        visited = [False] * (n + 1)
        stack = [start]
        visited[start] = True
        while stack:
            node = stack.pop()
            if node == target:
                return True
            for neighbor, _ in adj_list[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)
        return False

    def find_best_pair(target):
        visited_s = [False] * (n + 1)
        parent_s = [-1] * (n + 1)
        queue = [s]
        visited_s[s] = True
        path_edges_s = []

        # BFS from s
        while queue:
            node = queue.pop(0)
            if node == target:
                break
            for neighbor, idx in adj[node]:
                if not visited_s[neighbor]:
                    visited_s[neighbor] = True
                    parent_s[neighbor] = idx
                    path_edges_s.append(idx)
                    queue.append(neighbor)

        return target in visited_s

    def find_path_with_edges(start, target, blocked_edges):
        visited = [False] * (n + 1)
        parent = [-1] * (n + 1)
        edge_path = [[] for _ in range(n + 1)]
        queue = [start]
        visited[start] = True

        while queue:
            node = queue.pop(0)
            if node == target:
                # Reconstruct path
                path = []
                curr = target
                while curr != start and parent[curr] != -1:
                    eid = parent[curr]
                    path.append(eid)
                    curr = edges[eid - 1][0] if edges else 0  # Simplification
                return True

            for neighbor, idx in adj[node]:
                if idx in blocked_edges:
                    continue
                if not visited[neighbor]:
                    visited[neighbor] = True
                    parent[neighbor] = idx
                    edge_path[neighbor] = idx
                    queue.append(neighbor)
        return visited[target]

    def remove_and_check(bad_edges):
        visited = [False] * (n + 1)
        queue = [s]
        visited[s] = True
        while queue:
            node = queue.pop(0)
            if node == t:
                return False, []
            for neighbor, idx in adj[node]:
                if idx in bad_edges:
                    continue
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return True, []

    # Check if already disconnected
    disconnected, bad = remove_and_check(set())
    if not disconnected:
        # s and t are already disconnected
        return "0\n0\n"

    result_cost = float('inf')
    result_edges = []

    # Try removing 1 edge
    for i in range(m):
        idx = edges[i][3]
        blocked = {idx}
        disconnected, bad = remove_and_check(blocked)
        if not disconnected:
            cost = edges[i][2]
            if cost < result_cost:
                result_cost = cost
                result_edges = [idx]

    # Try removing 2 edges - only among incident edges to s or t or their neighbors
    try_edges = [idx for _, _, _, idx in edges]

    # Collect incident edges to s and t
