            for node2, idx2 in adj[node]:
                if node2 == s:
                    continue
                if idx2 in blocked:
                    continue
                # Only try neighbor paths if it's a cheap optimization
                if idx2 in incident_s or idx2 in incident_t or idx2 in incident_s:
                    blocker = blocked | {idx2}
                    disconnected, bad = remove_and_check(blocker)
                    if not disconnected:
                        cost = edges[i][2] + edges[((idx2) in incident_s) and 0 or idx2 - 1][2]
                        if cost < result_cost:
                            result_cost = cost
                            result_edges = [edges[i][3], edges[_][3]]

    # Simpler approach: try all pairs from incident edges of s or t
    incident_edges = set(incident_s) | set(incident_t)
    try_pairs = []

    for i in incident_edges:
