            if i < j:
                try_pairs.append((i, j))

    for i, idx1 in enumerate(sorted(try_pairs)):
        idx2, = try_pairs[i] if i < len(try_pairs) else None

        if idx2 is None:
            continue

        blocker = {idx1, idx2}
        disconnected, _ = remove_and_check(blocker)
        if not disconnected:
            cost = edges[[x[3] == idx1 or 0 for x in edges].index(idx1)][2] \
                  + edges[[x[3] == idx2 or 0 for x in edges].index(idx2)][2]
            if cost < result_cost:
                result_cost = cost
                result_edges = [idx1, idx2]

    if result_cost == float('inf'):
        return "-1"

    result_edges.sort()
    return f"{result_cost}\n2\n{' '.join(map(str, result_edges))}"
