    for _, _, k in queries:
        k_values.add(k)
    k_list = sorted(list(k_values))

    queries_by_k = {}
    for q_idx, (l, r, k) in enumerate(queries):
        if k not in queries_by_k:
            queries_by_k[k] = []
        queries_by_k[k].append((l, r))

    prefix_counts = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_counts[i] = prefix_counts[i - 1] + e[i - 1]

    def get_counts(l, r):
        if l == 1:
            return prefix_counts[r]
        return prefix_counts[r] - prefix_counts[l - 1]

    def power(a, b):
        res = 1
        a %= MOD
        while b > 0:
            if b % 2 == 1:
                res = res * a % MOD
            a = a * a % MOD
            b //= 2
        return res

    def modInverse(n):
        return power(n, MOD - 2)

    def nCr_mod(n, r, fact, inv):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv[r] % MOD * inv[n - r] % MOD

    def total_permutations(counts, total_n, fact, inv):
        result = 1
        rem_count = total_n
        for k_val in counts:
            result = result * nCr_mod(k_val, k_val, fact, inv) % MOD
            rem_count -= k_val
        result = result * fact[rem_count] % MOD
        return result

    MAX_fact = max(n + k for k in k_list) + n + m * max(k_list) + 1000
    MAX_fact = min(MAX_fact, 5000000) if MAX_fact > 3000000 else MAX_fact

    fact = [1] * MAX_fact
    inv = [1] * MAX_fact

    for i in range(1, MAX_fact):
        fact[i] = fact[i - 1] * i % MOD

    inv[MAX_fact - 1] = modInverse(fact[MAX_fact - 1])
    for i in range(MAX_fact - 2, -1, -1):
        inv[i] = inv[i + 1] * (i + 1) % MOD

    results = []

    for k in k_list:
        if k not in queries_by_k:
            continue

        c_prime = [cnt[j] + k for j in range(1, m + 1)]
