            valid = True
            for j in range(1, m + 1):
                if needed[j] > c_prime[j - 1]:
                    valid = False
                    break

            if not valid:
                results.append('0')
                continue

            total_ways = 1
            for j in range(1, m + 1):
                total_ways = total_ways * nCr_mod(c_prime[j - 1], needed[j], fact, inv) % MOD

            variant_ways = 1
