        parent = list(range(n + 2))

        def find(i):
            while parent[i] != i:
                parent[i] = parent[parent[i]]  # Path compression
                i = parent[i]
            return i

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            return root_i != root_j if root_i != root_j else False

        total_occupied = 0
        last = 0
        accepted = 0

        for l, r in offers:
            if r - l + 1 < x:
                continue

            root_l = find(l)
            root_r = find(r)

            # Check if [l, r] is separated from [last+1, last] by an unoccupied gap
            if find(last) != root_l:
                merged = False
                for i in range(last + 1, l):
                    root_gap = find(i)
                    if root_gap != find(i + 1):
                        # Gap exists between last+1 and l
                        merged = True
                        break

                if not merged:
                    # No gap, only accept if l - 1 <= last, meaning it's contiguous
                    if l <= last + 1:
