            # Simplified: accept if length >= x and no overlap with already accepted
            if r <= n and not (r <= last or l <= last):
                root_l = find(l)
                root_r = find(r)

                if root_l != root_r:
                    parent[root_l] = root_r
                    total_occupied += r - l + 1
                    accepted += 1
                    last = max(last, r)

