2. Find numbers representable as sum of two positive squares (Bob lucky)
3. Count numbers satisfying both conditions

From number theory: A prime can be written as sum of two squares iff p = 2 or p ≡ 1 (mod 4). For these primes, both squares are from positive integers.

Solution uses segmented sieve to efficiently count primes in large ranges.

```python
import math

def solution(input_data):
    l, r = map(int, input_data.strip().split())

    if l > r:
        return "0\n"

    # Generate primes up to sqrt(r) for segmented sieve
    sqrt_r = int(math.isqrt(r))
    if sqrt_r < 2:
        small_primes = []
    else:
        limit = sqrt_r + 1
        is_prime_small = [True] * (limit + 1)
        is_prime_small[0] = is_prime_small[1] = False

        for i in range(2, int(math.isqrt(limit)) + 1):
            if is_prime_small[i]:
                for j in range(i * i, limit + 1, i):
                    is_prime_small[j] = False

        small_primes = [i for i in range(2, limit + 1) if is_prime_small[i]]

    # Sieve the range [l, r]
    size = r - l + 1
    is_prime = [True] * size

    for p in small_primes:
        if p * p > r:
            break

        # Find first multiple of p >= l
        start = ((l + p - 1) // p) * p

        # Start from max(start, p*p) for correctness
        if start < p * p:
            start = p * p

        if start > r:
            continue

        # Mark multiples
        for i in range(start - l, size, p):
            is_prime[i] = False

    # Count special primes (p = 2 or p % 4 == 1)
    count = 0
    for i in range(size):
        if is_prime[i]:
            p = l + i
            if p == 2 or p % 4 == 1:
                count += 1

    return str(count) + "\n"


