                        path_tuple = list(path)
                        path_tuple.append((nr, nc, d))
                        stack.append((nr, nc, path_tuple))
                    else:
                        turn_on(r, c)
                        if visible(r, c, dr, dc):
                            visited.add((nr, nc))
                            path_tuple = list(path)
                            path_tuple.append((nr, nc, d))
                            stack.append((nr, nc, path_tuple))
                        else:
                            stack.append((r, c, path))

        return None

    for a, b in [(x0, y0)]:
        for nr, nc in range(1, n+1):
