def find_permutation(N, K):
    if K > N:
        return "-1"

    # For K = 0, handled above, so K >= 1 now

    # For N = 1, K >= 1: impossible since abs(1 - 1) = 0 < K
    if N == 1 and K >= 1:
        return "-1"

    # Check if each position has at least 2 valid value options
    # (to allow some flexibility for derangement-like assignment)
    has_valid = True
    for i in range(1, N + 1):
        count = 0
        for val in range(1, N + 1):
            if abs(val - i) >= K:
                count += 1
        if count == 0:
            has_valid = False
            break

    if not has_valid:
        return "-1"

    # Greedy approach to find lexicographically smallest permutation
    used = set()
    perm = []

    for i in range(1, N + 1):
        # Find smallest available value that satisfies the constraint
        placed = False
        for val in sorted(range(1, N + 1)):
            if val not in used and abs(val - i) >= K:
                used.add(val)
                perm.append(val)
                placed = True
                break

        if not placed:
            # Couldn't find a valid value - try backtracking/hard reset
            return "-1"

    # Verify the result
    for i in range(N):
        if abs(perm[i] - (i + 1)) < K:
            return "-1"

