        idx += 1

    B = []
    for i in range(n):
        B.append(list(map(int, lines[idx].split())))
        idx += 1

    def stable_sort(table, col):
        indices = list(range(n))
        indices.sort(key=lambda i: table[i][col])
        new_table = []
        for i in indices:
            new_table.append(table[i][:])
        return new_table

    # Check if rows can be matched
    b_row_queues = {}
    for i in range(n):
        row_key = tuple(B[i])
        if row_key not in b_row_queues:
            b_row_queues[row_key] = []
        b_row_queues[row_key].append(i)

    a_to_b = []
    for i in range(n):
        row_key = tuple(A[i])
        if row_key not in b_row_queues or not b_row_queues[row_key]:
            return "-1"
        b_idx = b_row_queues[row_key].pop(0)
        if tuple(B[b_idx]) != row_key:
            pass  # Already checked
        a_to_b.append(b_idx)

    # Try sorting by each column once in sequence
    for cols in range(m):
        col = cols + 1
        A_sorted = stable_sort([row[:] for row in A], col - 1)
        if A_sorted == [row[:] for row in B]:
            # Found solution
            output_lines = []
            output_lines.append("1")
            output_lines.append(str(col))
            return "\n".join(output_lines)

    # Try more patterns if greedy doesn't work
    # Sort by columns in order 1, 2, 3, ..., m
    columns = list(range(1, m + 1))
    for cols in columns:
        A_sorted = stable_sort([row[:] for row in A], cols - 1)
        if A_sorted == [row[:] for row in B]:
            output_lines = ["1"]
            output_lines.append(str(cols))
            return "\n".join(output_lines)

    # If permutation is identity (no change needed)
    if a_to_b == list(range(n)):
        output_lines = ["0"]
        return "\n".join(output_lines)

    # If we can't find solution after multiple attempts, try more
    current_A = [row[:] for row in A]
    for _ in range(5000):
        for col in range(1, m + 1):
            current_A = stable_sort(current_A, col - 1)
            if current_A == [row[:] for row in B]:
                output_lines = ["1"]
                # Try variations of column sequences
                for attempt in range(min(m + 1, 5000)):
                    cols_to_use = []
                    for i in range(attempt):
                        cols_to_use.append(i + 1)
                    if cols_to_use:
                        break
                if cols_to_use:
                    # Simple approach - try appending more columns
                    result_cols = [col]
                    if result_cols:
                        output_lines.append(" ".join(map(str, result_cols)))
                        return "\n".join(output_lines)
                return "-1"
        if current_A == [row[:] for row in B]:
