            primes.append(i)
            for j in range(i*i, max_n + 1, i):
                is_prime[j] = False

    def get_prime_factorization(n):
        factors = []
        temp = n
        for p in primes:
            if p * p > temp:
                break
            if temp % p == 0:
                count = 0
                while temp % p == 0:
                    temp //= p
                    count += 1
                factors.append(count)
        if temp > 1:
            factors.append(1)
        return factors

    def nCr(n, r):
        if r < 0 or r > n:
            return 0
        if r == 0 or r == n:
            return 1
        if r > n // 2:
            r = n - r

        num = 1
        den = 1
        for i in range(r):
            num = (num * (n - i)) % MOD
            den = (den * (i + 1)) % MOD
        return (num * pow(den, MOD - 2, MOD)) % MOD

    for i in range(1, min(q + 1, len(lines))):
        r, n = map(int, lines[i].split())

        if n == 1:
            results.append("1")
            continue

        factors = get_prime_factorization(n)

        if r == 0:
            result = (1 << len(factors)) % MOD
        elif r == 1:
            result = 0
            for exp in factors:
                result = (result + exp + 1) % MOD
        else:
            result = 1
            for exp in factors:
                result = (result * nCr(exp + 2 * r - 2, 2 * r - 2)) % MOD

        results.append(str(result))

    return '\n'.join(results)
