    for size in shoe_sizes:
        # Process shoes of this size, sorted by price descending for consistency
        for price, sid in sorted(shoes_by_size[size], key=lambda x: x[0], reverse=True):
            if sid in used_shoes:
                continue

            # Find eligible customers (foot size = size or foot size = size - 1)
            candidates = []
            if size in customers_by_foot:
                for money, cid in customers_by_foot[size]:
                    if money >= price and cid not in used_customers:
                        candidates.append((money, cid))
            if size - 1 in customers_by_foot:
                for money, cid in customers_by_foot[size - 1]:
                    if money >= price and cid not in used_customers:
                        candidates.append((money, cid))

            if candidates:
                # Pick the customer with most money (for consistent output)
                candidates.sort(key=lambda x: x[0], reverse=True)
                _, cid = candidates[0]

                profit += price
                result.append((cid, sid))
                used_customers.add(cid)
                used_shoes.add(sid)
                break  # Each customer buys only one shoe, so one assignment per shoe
                # Actually wait - one shoe, one customer. This is correct.

    # Output
    output = [str(profit), str(len(result))]
    for cid, sid in result:
        output.append(f"{cid} {sid}")

    return '\n'.join(output)


